import { useLayoutEffect, useRef, useState } from 'react';
import { Board } from './board/Board.tsx';
import { Controls } from './controls/Controls.tsx';
import { Reproduction } from './controls/Reproduction.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { useGame } from './session/use-game.ts';
import { isWon } from './game.ts';
import { formatElapsed } from './elapsed-time.ts';
import { useTournament } from './tournament/use-tournament.ts';
import { TournamentContent, TournamentHeading } from './tournament/TournamentScreen.tsx';
import { LeaveDialog } from './tournament/LeaveDialog.tsx';
import { encodeTournament } from './tournament/format.ts';
import { currentPlayer, matchWinner, TournamentPhase } from './tournament/rules.ts';
import type { LeaveRequest } from './tournament/LeaveDialog.tsx';
import type { TournamentDocument } from './tournament/format.ts';
import './game.css';

export function Game() {
  const controller = useGame();
  const tournament = useTournament(controller.announce);
  const [request, setRequest] = useState<LeaveRequest | null>(null);
  const [returned, setReturned] = useState(false);
  const heading = useRef<HTMLHeadingElement>(null);
  const { session } = controller;
  const { game } = session;
  const board = useRef<BoardFocus>(null);
  const event = tournament.tournament;
  const playing = tournament.open && event?.phase === TournamentPhase.playing && !session.paused;
  useLayoutEffect(() => {
    if (!tournament.open && returned) heading.current?.focus();
  }, [tournament.open, returned]);
  function confirm(action: () => void, unfinished: boolean): void {
    if (unfinished) setRequest({ proceed: action, trigger: document.activeElement });
    else action();
  }
  function enterTournament(): void {
    confirm(() => { controller.enterTournament(); tournament.enter(); }, game.started && !isWon(game));
  }
  function leaveTournament(): void {
    confirm(() => {
      controller.leaveTournament(); tournament.leave(); setReturned(true);
    }, event !== null && event.phase !== TournamentPhase.completed);
  }
  function startTurn(): void {
    if (!event) return;
    if (event.phase === TournamentPhase.playing && session.paused) controller.resume();
    else {
      const code = tournament.begin();
      if (!code) return;
      controller.startTournamentTurn(code);
    }
    controller.announce(`Now playing: ${currentPlayer(event)}`);
  }
  function activate(index: number): void {
    const next = controller.activate(index);
    if (!playing || !isWon(next)) return;
    const finished = tournament.finish(next);
    if (finished?.phase === TournamentPhase.completed) {
      const winner = matchWinner(finished, finished.currentMatch);
      controller.announce(`Pair found. All pairs found in ${next.moves} moves and ${formatElapsed(next.elapsedMs)}. Champion: ${winner == null ? '' : finished.players[winner - 1]}`);
    }
  }
  function loadTournament(document: TournamentDocument): void {
    confirm(() => {
      controller.pause();
      tournament.load(document);
      if (document.game) {
        controller.startTournamentTurn(document.game.boardCode, document.game);
        controller.announce('Loaded tournament. Select Start turn to continue.');
      }
