    <main>
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <p className="intro">Reveal two cards. Match their shape and marker to keep the pair.</p>
      {tournament.open ? (
        <TournamentHeading controller={tournament} paused={session.paused}
          startTurn={startTurn} leave={leaveTournament} />
      ) : <>
