      <Controls size={game.size} newGame={controller.newGame} restart={controller.restart}
        tournament={enterTournament} />
      <GameStatus
        game={game}
        best={session.preferences.bestMoves[String(game.size)]}
        celebration={session.celebration}
      />
      <p id="board-help" className="help">
        Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
        reveals a card.
      </p>
      </>}
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={session.announcement}>{session.feedback}</span>
        </p>
      </div>
      {tournament.open ? (
        <TournamentContent controller={tournament} exportTournament={exportTournament}
          load={loadTournament} announce={controller.announce}>
          {playing && <>
            <GameStatus game={game} best={undefined} celebration={session.celebration} />
            <p id="board-help" className="help">Arrow keys move between cards. Enter or Space reveals a card.</p>
            <Board key={session.generation} game={game} activate={activate} ref={board} />
          </>}
